-- UDM Registry: Industry Crosswalk seeded from Universal Decoding Matrix_Master.xlsx
-- (Industry Crosswalk sheet — ISIC Rev.4 ontology anchor with NAICS 2022 + GICS bridges).
CREATE TABLE IF NOT EXISTS udm_crosswalk (
  ontology_id TEXT PRIMARY KEY,
  industry TEXT,
  isic_section TEXT,
  isic_division TEXT,
  isic_title TEXT,
  naics_bridge TEXT,
  gics_sector TEXT,
  gics_industry TEXT,
  mapping_status TEXT,
  bridge_path TEXT
);
DELETE FROM udm_crosswalk;
